#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char *a = malloc(16);
    strcpy(a, "secret");
    char *alias = a;

    free(a);                      /* block goes back to the allocator */
    char *b = malloc(16);         /* often the very same address */
    strcpy(b, "attacker-data");

    printf("%s\n", alias);        /* UB: usually prints attacker-data */
    free(b);
    free(alias);                  /* double free of the same block */
    return 0;
}

#define SAFE_FREE(p) do { free(p); (p) = NULL; } while (0)

int *p = malloc(sizeof *p);
*p = 42;
SAFE_FREE(p);
if (p) printf("%d\n", *p);   /* skipped: p is NULL */
SAFE_FREE(p);                 /* harmless: free(NULL) */

int x = 4; float y = 5.5f;
void *vp = &x;
printf("%d\n", *(int *)vp);       /* cast, then dereference */
vp = &y;
printf("%.1f\n", *(float *)vp);

int *wild;            /* indeterminate: do not use */
int *safe = NULL;     /* well-defined empty pointer */
if (safe == NULL) puts("no object");

char *p = malloc(32);
free(p);
free(p);                 /* UB: abort in glibc, silent corruption elsewhere */

char buf[32];
free(buf);               /* UB: not heap memory */
char *q = malloc(32);
free(q + 8);             /* UB: not the start of the block */

typedef struct Thing Thing;
void thing_free(Thing **pp) {
    if (!pp || !*pp) return;
    free((*pp)->name);
    free(*pp);
    *pp = NULL;           /* caller's pointer cleared, double free harmless */
}

/* wrong */
for (Node *cur = head; cur; cur = cur->next)
    free(cur);                     /* reads cur->next after free */

/* right */
for (Node *cur = head, *next; cur; cur = next) {
    next = cur->next;
    free(cur);
}
